+/// Return the number of CLZ-window misses this factor would encounter under the
+/// currently enabled thin schedule. This is diagnostic-only; it mirrors the
+/// classical PZ replay so tail-nonce/support searches can reject low-CLZ
+/// profiles without a full trusted eval.
+pub fn thin_factor_clz_window_misses_u256(value: U256) -> usize {
+    if value.is_zero() {
+        return SHRUNKEN_PZ_NSTEPS;
+    }
+    let Some(thin) = thin_schedule() else {
+        return 0;
+    };
+    let p = secp_p();
+    let half = p >> 1;
+    clz_window_misses_sample(widen_u256(value), p, half, &thin.widths)
+}
